import{_ as d,o as r,c as a,a5 as e}from"./chunks/framework.bIR-4glx.js";const f=JSON.parse('{"title":"术语与方法索引","description":"用一页索引解释《人生进阶指南》的核心词汇、证据标准、工具入口与阅读路径，帮助读者在章节之间迁移。","frontmatter":{"title":"术语与方法索引","description":"用一页索引解释《人生进阶指南》的核心词汇、证据标准、工具入口与阅读路径，帮助读者在章节之间迁移。","updated":"2026-09-07T00:00:00.000Z"},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1788739200000}'),s={name:"reference/glossary.md"};function n(o,t,h,g,i,l){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="术语与方法索引" tabindex="-1">术语与方法索引 <a class="header-anchor" href="#术语与方法索引" aria-label="Permalink to &quot;术语与方法索引&quot;">​</a></h1><p>这不是一份把生活变成术语表的企图。它只是给书中反复出现的词留下一处稳定的落脚点：当你忘记一个词是什么意思，或不知道下一步该打开哪一页时，从这里回来。</p><h2 id="怎么使用" tabindex="-1">怎么使用 <a class="header-anchor" href="#怎么使用" aria-label="Permalink to &quot;怎么使用&quot;">​</a></h2><p>先找到你正在面对的任务，再沿着“定义 → 证据 → 下一步”阅读。一个词如果不能帮助你完成任务、留下样本或做出更好的决定，就不必为了记住它而记住它。</p><h2 id="问题与目标" tabindex="-1">问题与目标 <a class="header-anchor" href="#问题与目标" aria-label="Permalink to &quot;问题与目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在本书中的意思</th><th>从这里继续</th></tr></thead><tbody><tr><td><strong>真实问题</strong></td><td>有具体场景、受影响的人和需要完成的动作，而不是“我想变好”</td><td><a href="./../threads/part-1/1-understanding">认知篇</a></td></tr><tr><td><strong>场景</strong></td><td>能力将在何时、何地、对谁被使用</td><td><a href="./../threads/part-1/0-cefr">CEFR 目标与自测</a></td></tr><tr><td><strong>完成标准</strong></td><td>一个别人可以观察、复查或复述的结果</td><td><a href="./../templates/ai-task-brief">AI 任务简报</a></td></tr><tr><td><strong>评估集</strong></td><td>用正常、边界、缺失/冲突和真实脱敏样本检查输出，而不是只展示模型擅长的例子</td><td><a href="./../templates/ai-task-brief">AI 任务简报</a></td></tr><tr><td><strong>主问题</strong></td><td>一周只追踪的一个可回答问题</td><td><a href="./../threads/part-5/90-day-plan">九十日行动篇</a></td></tr></tbody></table><h2 id="证据与判断" tabindex="-1">证据与判断 <a class="header-anchor" href="#证据与判断" aria-label="Permalink to &quot;证据与判断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在本书中的意思</th><th>常见误区</th></tr></thead><tbody><tr><td><strong>基线</strong></td><td>在工具介入或集中训练前保存的原始样本</td><td>用感觉或成品代替第一版</td></tr><tr><td><strong>证据</strong></td><td>能回到作品、录音、测试、来源或真实反馈的记录</td><td>把时长、收藏数或聊天记录当作能力证明</td></tr><tr><td><strong>事实</strong></td><td>可以指出来源、时间、样本或直接观察的内容</td><td>把解释写成已经证实的因果</td></tr><tr><td><strong>解释</strong></td><td>对事实的理解，可能有用，也可能需要修正</td><td>只因为它听起来合理就停止核验</td></tr><tr><td><strong>假设</strong></td><td>等待下一次行动检验的判断</td><td>把愿望或模型回答写成结论</td></tr><tr><td><strong>推断边界</strong></td><td>区分原文明确说的、证据支持的和自己补出的部分</td><td>把标题、情绪或单一案例当作全貌</td></tr><tr><td><strong>叙事压缩</strong></td><td>用一句话或一条因果链把复杂经历整理成可传播的故事</td><td>把偶然、他人贡献和未知删掉后误当成全貌</td></tr><tr><td><strong>回望偏差</strong></td><td>事后用已经知道的结果解释当时的选择</td><td>把后来才出现的信息倒灌回过去</td></tr></tbody></table><h2 id="学习动作" tabindex="-1">学习动作 <a class="header-anchor" href="#学习动作" aria-label="Permalink to &quot;学习动作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在本书中的意思</th><th>相关章节</th></tr></thead><tbody><tr><td><strong>主动回忆</strong></td><td>合上材料后自己回答、复述、书写或完成任务</td><td><a href="./../threads/part-1/1-understanding">认知篇</a></td></tr><tr><td><strong>完整学习回路</strong></td><td>定义任务、保存首版、诊断错误、定向输入、主动产出、记录反馈与状态的六步循环</td><td><a href="./../threads/part-1/1-understanding">认知篇</a></td></tr><tr><td><strong>首版条件</strong></td><td>记录第一次尝试的材料、时间、工具、帮助和完成标准，使后续比较不被润色成品混淆</td><td><a href="./../templates/english-diagnostic">英语能力诊断</a></td></tr><tr><td><strong>容量模式</strong></td><td>根据当天的注意、身体、时间和责任，选择完整、降档、最小或暂停版本的行动条件</td><td><a href="./../threads/part-4/daily-system">生活系统篇</a></td></tr><tr><td><strong>间隔练习</strong></td><td>在多个时间点回来，而不是一次集中刷完</td><td><a href="./../threads/part-1/2-vocabulary">词汇篇</a></td></tr><tr><td><strong>未知项决策队列</strong></td><td>对每个未知词决定放过、推断、速查、主动学习或专业核验，并记录为什么</td><td><a href="./../templates/vocabulary-audit">词汇证据卡</a></td></tr><tr><td><strong>词汇八维</strong></td><td>分开记录词形、声音、当前义项、搭配、语法、语域、概念边界和调用条件</td><td><a href="./../threads/part-1/2-vocabulary">词汇篇</a></td></tr><tr><td><strong>接受性 / 产出性词汇</strong></td><td>前者是在听读中理解，后者是在没有答案展示时主动说写；两者不能互相冒充</td><td><a href="./../threads/part-1/2-vocabulary">词汇篇</a></td></tr><tr><td><strong>形式—意义选择</strong></td><td>不把语法只看作规则名称，而是比较不同结构怎样改变时间、参与者、条件、否定范围、逻辑或确定性</td><td><a href="./../threads/part-1/grammar">语法篇</a></td></tr><tr><td><strong>语法对比卡</strong></td><td>围绕一个真实任务保存原句、可能理解、真实意图、形式对比、修改理由与延迟复测</td><td><a href="./../templates/grammar-evidence">语法证据卡</a></td></tr><tr><td><strong>参考变体</strong></td><td>为减少初期决策而选择的一套相对稳定的词典音频、拼写或发音参照；它不代表其他英语变体低一等</td><td><a href="./../threads/part-1/5-speaking">口语篇</a></td></tr><tr><td><strong>可理解度 / 理解难度</strong></td><td>前者记录听众实际恢复了多少意思，后者记录理解需要多少猜测、重听或确认；两者都不同于口音显著度</td><td><a href="./../threads/part-1/5-speaking">口语篇</a></td></tr><tr><td><strong>听众复述</strong></td><td>听众不看稿，用自己的话说出主旨、细节、数字、责任与下一步，以检查声音实际传达了什么</td><td><a href="./../templates/speaking-evidence">口语证据卡</a></td></tr><tr><td><strong>首听基线</strong></td><td>在预先记录的字幕、暂停、倍速、设备与环境条件下完成第一次播放，并保留原始主旨、细节、时间段和行动判断</td><td><a href="./../templates/listening-audit">听力证据卡</a></td></tr><tr><td><strong>支架阶梯</strong></td><td>从无字幕首听、局部重听、英文转写到最小背景帮助，再关闭文字并延迟撤架的可升降支持</td><td><a href="./../threads/part-1/3-listening">听力篇</a></td></tr><tr><td><strong>意义重构</strong></td><td>不逐字重复原音，而是恢复主旨、关系、关键细节与下一步，并用复述、流程、决定或交接表达</td><td><a href="./../threads/part-1/3-listening">听力篇</a></td></tr><tr><td><strong>首读基线</strong></td><td>在预先记录的时间、词典、翻译、搜索与 AI 条件下完成第一次阅读，保留原始主旨、结构、未知项与行动判断</td><td><a href="./../templates/reading-evidence">阅读证据卡</a></td></tr><tr><td><strong>主张地图</strong></td><td>将段落标成背景、问题、主张、理由、证据、限制与行动，并保留原文位置</td><td><a href="./../threads/part-1/4-reading">阅读篇</a></td></tr><tr><td><strong>技术事实卡</strong></td><td>把文档目标、版本、前置条件、最小输入、预期/实际输出、失败与下一测试放在一页</td><td><a href="./../templates/reading-evidence">阅读证据卡</a></td></tr><tr><td><strong>窄读</strong></td><td>围绕同一主题或领域连续阅读多份材料，让背景知识、术语和结构重复出现</td><td><a href="./../threads/part-1/4-reading">阅读篇</a></td></tr><tr><td><strong>事实与责任账本</strong></td><td>为写作中的事实、数字、引语、经历、推断和他人信息记录来源、版本、权限、置信度与责任人</td><td><a href="./../threads/part-1/6-writing">写作篇</a></td></tr><tr><td><strong>反馈吸收</strong></td><td>对反馈逐项决定采纳、部分采纳、拒绝或延后，记录理由，并在平行文本中检查能否独立使用</td><td><a href="./../templates/writing-evidence">写作证据卡</a></td></tr><tr><td><strong>署名决定</strong></td><td>交付前判断当前文本是否愿意署名、仍需核验、需要缩小范围或不应发布</td><td><a href="./../templates/writing-evidence">写作证据卡</a></td></tr><tr><td><strong>精听/精读</strong></td><td>用短材料核对细节、结构、证据和语言形式</td><td><a href="./../threads/part-1/3-listening">听力篇</a> · <a href="./../threads/part-1/4-reading">阅读篇</a></td></tr><tr><td><strong>平行材料</strong></td><td>难度和任务相近、但内容不同的材料，用来测试迁移</td><td><a href="./../templates/reading-evidence">阅读证据卡</a></td></tr><tr><td><strong>迁移</strong></td><td>换主题、听众、时间或任务后仍能完成相近动作</td><td><a href="./../templates/90-day-cycle">九十日行动总表</a></td></tr><tr><td><strong>延迟保持</strong></td><td>经过一段时间、撤掉最近提示后仍能完成相近任务</td><td><a href="./../threads/part-3/5-evidence-and-transfer">证据篇</a></td></tr><tr><td><strong>证据链</strong></td><td>把基线、即时表现、延迟保持、迁移和下一步放在同一页的记录</td><td><a href="./../templates/evidence-chain">证据链模板</a> · <a href="./../threads/part-3/5-evidence-and-transfer">证据篇</a></td></tr><tr><td><strong>变式</strong></td><td>保留核心动作，同时改变主题、听众、时间或限制，用来检验是否真的学会</td><td><a href="./../threads/part-4/rhythm-and-compounding">节律篇</a></td></tr><tr><td><strong>学习主体权</strong></td><td>学习者参与定义目标、提交自己的首版、表达容量、质疑反馈，并承担与年龄和情境相称的责任</td><td><a href="./../threads/part-4/family-learning">家庭学习篇</a></td></tr><tr><td><strong>岗位语言地图</strong></td><td>从真实岗位描述与流程提取招聘沟通、项目说明、技术追问、异步写作等语言任务，并对应现有证据</td><td><a href="./../threads/part-1/8-job-search-english">求职英语篇</a></td></tr></tbody></table><h2 id="工具与交付" tabindex="-1">工具与交付 <a class="header-anchor" href="#工具与交付" aria-label="Permalink to &quot;工具与交付&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在本书中的意思</th><th>相关章节</th></tr></thead><tbody><tr><td><strong>任务卡</strong></td><td>写清场景、输入、动作、边界、验收和责任人的一页记录</td><td><a href="./../templates/ai-task-brief">AI 任务简报</a></td></tr><tr><td><strong>学习状态文件</strong></td><td>保存在会话之外的版本化事实页，记录目标、证据、错误、边界、交接和下一任务</td><td><a href="./../templates/learning-state">学习状态</a> · <a href="./../templates/toolkit-walkthrough">工具箱实战</a></td></tr><tr><td><strong>案例复盘</strong></td><td>将公开经历拆成来源、事实、判断、结果和可迁移原则的记录</td><td><a href="./../templates/ai-case-review">AI 经历案例复盘</a></td></tr><tr><td><strong>证据卡</strong></td><td>为听、读、说、写某一项能力保存首版、反馈和复测的模板</td><td><a href="./../threads/part-0/prologue">四项能力工具</a></td></tr><tr><td><strong>读者实践回执</strong></td><td>私下记录阅读入口、实际行动、即时结果、延迟复测、迁移与编辑反馈的两次记录</td><td><a href="./../templates/reader-field-note">读者实践回执</a></td></tr><tr><td><strong>家庭学习共同协议</strong></td><td>学习者与家长分别记录目标、担心、支持、AI 与数据边界，并用十四天证据共同复查的私密工作表</td><td><a href="./../templates/family-learning-agreement">家庭学习共同协议</a></td></tr><tr><td><strong>求职英语证据卡</strong></td><td>将真实岗位、无稿基线、故事、陌生追问、异步写作、延迟复测和诚信边界放在同一份记录中</td><td><a href="./../templates/interview-evidence">求职英语证据卡</a></td></tr><tr><td><strong>语法证据卡</strong></td><td>一次只追踪一个高影响结构，连接真实任务基线、意义对比、四项调用、反馈分类与第 14 天迁移</td><td><a href="./../templates/grammar-evidence">语法证据卡</a></td></tr><tr><td><strong>听力证据卡</strong></td><td>连接材料条件、无字幕首听、六层错误地图、字幕支架、意义重构、行动输出与平行材料迁移的记录</td><td><a href="./../templates/listening-audit">听力证据卡</a></td></tr><tr><td><strong>阅读证据卡</strong></td><td>连接来源版本、首读、六层障碍、主张证据、技术事实、多来源比较、真实输出与延迟迁移的记录</td><td><a href="./../templates/reading-evidence">阅读证据卡</a></td></tr><tr><td><strong>写作证据卡</strong></td><td>连接真实受众、无辅助初稿、事实来源、翻译变化、五次修订、反馈吸收、AI 使用、异步交付与署名责任的记录</td><td><a href="./../templates/writing-evidence">写作证据卡</a></td></tr><tr><td><strong>词汇证据卡</strong></td><td>连接真实任务、首遇基线、未知项决定、八维核验、无提示调用、错误修复和延迟迁移的记录</td><td><a href="./../templates/vocabulary-audit">词汇证据卡</a></td></tr><tr><td><strong>口语证据卡</strong></td><td>连接参考变体、三种无稿基线、听众复述、理解成本、互动修复、陌生追问与延迟迁移的私密记录</td><td><a href="./../templates/speaking-evidence">口语证据卡</a></td></tr><tr><td><strong>互动修复</strong></td><td>没听清、范围不明或暂时未知时，请求重复、确认、争取思考时间并总结共识</td><td><a href="./../threads/part-1/5-speaking">口语篇</a> · <a href="./../threads/part-1/8-job-search-english">求职英语篇</a></td></tr><tr><td><strong>作品</strong></td><td>能被别人阅读、使用、质疑或改进的输出，不限于产品</td><td><a href="./../threads/part-3/4-artifacts-and-delivery">作品篇</a></td></tr><tr><td><strong>交付</strong></td><td>在真实受众、用户或约束下完成并接受结果</td><td><a href="./../threads/part-5/90-day-plan">九十日行动篇</a></td></tr><tr><td><strong>人工门</strong></td><td>AI 可以协助，但来源、事实、权限、隐私、质量、成本和最终责任必须在发布或执行前由具名的人确认</td><td><a href="./../templates/ai-task-brief">AI 任务简报</a> · <a href="./../threads/part-3/2-ai-development-and-resource-layer">AI 项目开发</a></td></tr><tr><td><strong>速度债</strong></td><td>通过缩短即时用时却增加返工、核验、沟通或事故风险而欠下的真实成本</td><td><a href="./../templates/ai-learning-log">AI 学习记录</a></td></tr><tr><td><strong>AI 学习记录</strong></td><td>比较无 AI、辅助、延迟独立和平行任务，记录工具贡献与独立能力的私密工作纸</td><td><a href="./../templates/ai-learning-log">AI 学习记录</a></td></tr><tr><td><strong>回滚</strong></td><td>失败时暂停、降级、切换或恢复到已知可用状态</td><td><a href="./../threads/part-3/1-ai-learning">AI 学习与项目实践</a></td></tr></tbody></table><h2 id="生活与边界" tabindex="-1">生活与边界 <a class="header-anchor" href="#生活与边界" aria-label="Permalink to &quot;生活与边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在本书中的意思</th><th>相关章节</th></tr></thead><tbody><tr><td><strong>边界</strong></td><td>说明发生某件事时，我会如何保护自己并执行后果</td><td><a href="./../threads/part-2/relationships">关系篇</a></td></tr><tr><td><strong>恢复</strong></td><td>先恢复安全、身体、关系和可行动性，再谈效率和增长</td><td><a href="./../threads/part-2/recovery">恢复篇</a></td></tr><tr><td><strong>恢复模式</strong></td><td>根据当天安全、基本照料和可行动性选择安全、降档或重建负荷；它是生活记录语言，不是临床分级</td><td><a href="./../threads/part-2/recovery">恢复篇</a></td></tr><tr><td><strong>复工试载</strong></td><td>一次只增加时长、复杂度、责任或公开程度中的一个变量，再检查当天完成与次日代价</td><td><a href="./../threads/part-2/recovery">恢复篇</a></td></tr><tr><td><strong>支持协议</strong></td><td>写清支持者可以做什么、不能替代什么、何时升级求助，以及风险降低后如何归还控制权</td><td><a href="./../threads/part-2/recovery">恢复篇</a> · <a href="./../templates/life-practice-toolkit">生活进阶工作表</a></td></tr><tr><td><strong>最小秩序</strong></td><td>在混乱时期仍能重复的一个安全动作和一个可见结果</td><td><a href="./../templates/life-practice-toolkit">生活进阶工作表</a></td></tr><tr><td><strong>最小可行的一天</strong></td><td>根据当天容量保留安全、一个最小输出和下一步提示的日程版本</td><td><a href="./../threads/part-4/daily-system">生活系统篇</a></td></tr><tr><td><strong>精力预算</strong></td><td>把时间、注意力、身体和责任一起写进计划的可用容量估算</td><td><a href="./../threads/part-4/daily-system">生活系统篇</a></td></tr><tr><td><strong>回归动作</strong></td><td>中断后 24 小时内能够完成、并把人带回系统的最小输出</td><td><a href="./../threads/part-4/daily-system">生活系统篇</a></td></tr><tr><td><strong>节律</strong></td><td>在不同容量下仍能辨认和执行的一条行动模式，让重复、反馈与恢复沿时间连接</td><td><a href="./../threads/part-4/rhythm-and-compounding">节律篇</a></td></tr><tr><td><strong>复利</strong></td><td>今天的选择减少明天的犹豫、返工或恢复成本，使能力、信任、判断和恢复彼此支撑</td><td><a href="./../threads/part-4/rhythm-and-compounding">节律篇</a></td></tr><tr><td><strong>最小合同</strong></td><td>在坏日子里约定何时降档、保留什么动作，以及何时求助或升级风险的协议</td><td><a href="./../threads/part-4/rhythm-and-compounding">节律篇</a></td></tr><tr><td><strong>节律账本</strong></td><td>每周一页，记录主问题、保住的动作、有效反馈、反复阻力和下周要改变的条件</td><td><a href="./../templates/rhythm-ledger">节律账本模板</a> · <a href="./../threads/part-4/rhythm-and-compounding">节律篇</a></td></tr><tr><td><strong>代价</strong></td><td>时间、金钱、健康、关系、隐私和责任等需要被明确支付的部分</td><td><a href="./../threads/part-2/decision">选择篇</a></td></tr><tr><td><strong>可逆性</strong></td><td>一个选择能否暂停、撤回或用较小成本改回</td><td><a href="./../threads/part-2/decision">选择篇</a></td></tr><tr><td><strong>价值冲突</strong></td><td>两个重要目标无法同时被完整保留，需要明确优先级和每个选项会失去什么</td><td><a href="./../threads/part-2/decision">选择篇</a></td></tr><tr><td><strong>决定权</strong></td><td>对一项选择拥有最终签字或拒绝权限，并需要说明权限来源、受影响者和责任承担</td><td><a href="./../threads/part-2/decision">选择篇</a></td></tr><tr><td><strong>推翻证据</strong></td><td>在行动前写明哪一种事实或结果会让当前选择失去依据，防止只收集支持原结论的信息</td><td><a href="./../threads/part-2/decision">选择篇</a></td></tr><tr><td><strong>停止门槛</strong></td><td>用可观察的证据、成本、安全或责任信号触发暂停、停止、回滚或升级求助</td><td><a href="./../threads/part-2/decision">选择篇</a> · <a href="./../templates/life-practice-toolkit">生活进阶工作表</a></td></tr></tbody></table><h2 id="一句话记忆" tabindex="-1">一句话记忆 <a class="header-anchor" href="#一句话记忆" aria-label="Permalink to &quot;一句话记忆&quot;">​</a></h2><p>如果只能留下一个顺序：先把问题说清楚，再保存基线；用合适的工具做一次小任务，交给真实的人检验；把反馈写回下一步，力量不足时先恢复，不用羞耻替代计划。</p><p>相关入口：<a href="./../threads/part-0/prologue">序章：先不要急着改变人生</a> ｜ <a href="./../templates/90-day-cycle">九十日行动总表</a></p>',17)])])}const c=d(s,[["render",n]]);export{f as __pageData,c as default};
